package app.flowdrop.mobile.test;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import app.flowdrop.mobile.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
/** Runs the native services and MediaStore even when the emulator's System UI is unavailable. */
public final class NativeServiceSmoke extends Instrumentation {
 interface Condition{boolean test()throws Exception;}
 private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 private void await(Condition test,String message)throws Exception{long end=SystemClock.elapsedRealtime()+150000;while(SystemClock.elapsedRealtime()<end){if(test.test())return;SystemClock.sleep(200);}throw new AssertionError(message+"; sender="+SendService.state());}
 private void stage(String text){Bundle b=new Bundle();b.putString("stage",text);sendStatus(1,b);}
 @Override public void onCreate(Bundle state){super.onCreate(state);start();}
 @Override public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();ArrayList<Uri> sources=new ArrayList<>();AtomicReference<HostService> host=new AtomicReference<>();ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName name,IBinder binder){host.set(((HostService.LocalBinder)binder).getService());}public void onServiceDisconnected(ComponentName name){host.set(null);}};
 try{
  stage("starting_native_services");context.startForegroundService(new Intent(context,HostService.class));check(context.bindService(new Intent(context,HostService.class),connection,Context.BIND_AUTO_CREATE),"Cannot bind native host");await(()->host.get()!=null&&host.get().isReady(),"Native host did not start");String origin=host.get().getUrl();stage("native_host_ready");
  HashMap<String,byte[]> expected=new HashMap<>();JSONArray files=new JSONArray();String suffix=Long.toString(System.currentTimeMillis());String[] names={"native-"+suffix+".txt","native-empty-"+suffix+".bin","native-photo-"+suffix+".png"};byte[] big=new byte[1024*1024];for(int i=0;i<big.length;i++)big[i]=(byte)(i%251);byte[][] data={big,new byte[0],android.util.Base64.decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6ZQAAAABJRU5ErkJggg==",0)};
  for(int i=0;i<names.length;i++){ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,names[i]);values.put(MediaStore.MediaColumns.MIME_TYPE,i==2?"image/png":"application/octet-stream");values.put(MediaStore.MediaColumns.RELATIVE_PATH,"Download/FlowDropNativeTest");Uri uri=context.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);check(uri!=null,"Cannot create MediaStore source");sources.add(uri);try(OutputStream output=context.getContentResolver().openOutputStream(uri)){output.write(data[i]);}expected.put(names[i],data[i]);files.put(new JSONObject().put("uri",uri.toString()).put("name",names[i]).put("size",data[i].length).put("type",i==2?"image/png":"application/octet-stream"));}
  context.getSharedPreferences("native-send",0).edit().putString("request",files.toString()).commit();context.startForegroundService(new Intent(context,SendService.class).putExtra("origin",origin));await(()->"sent".equals(SendService.state().optString("status")),"Native SendService did not send sources");JSONObject sent=SendService.state().getJSONObject("transfer");String code=sent.getString("code");stage("native_send_complete");check(sent.getJSONArray("files").length()==3,"Native send lost files");
  context.startForegroundService(new Intent(context,ReceiveService.class).putExtra("origin",origin).putExtra("code",code));await(()->{JSONArray history=TransferHistory.read(context);int count=0;for(int i=0;i<history.length();i++)if("receive".equals(history.getJSONObject(i).optString("direction"))&&code.equals(history.getJSONObject(i).optString("code")))count++;return count==3;},"Native MediaStore receiver did not finish");stage("native_receive_complete");JSONArray history=TransferHistory.read(context);ArrayList<Uri> saved=new ArrayList<>();for(int i=0;i<history.length();i++){JSONObject item=history.getJSONObject(i);if(!"receive".equals(item.optString("direction"))||!code.equals(item.optString("code")))continue;Uri uri=Uri.parse(item.getString("uri"));saved.add(uri);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=context.getContentResolver().openInputStream(uri)){byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1)bytes.write(buffer,0,n);}check(Arrays.equals(expected.get(item.getString("name")),bytes.toByteArray()),"Saved bytes changed");try(Cursor cursor=context.getContentResolver().query(uri,new String[]{MediaStore.MediaColumns.IS_PENDING,MediaStore.MediaColumns.RELATIVE_PATH},null,null,null)){check(cursor!=null&&cursor.moveToFirst()&&cursor.getInt(0)==0,"Partial file exposed");check(cursor.getString(1).startsWith(item.getString("name").endsWith(".png")?"DCIM/FlowDrop":"Download/FlowDrop"),"Wrong saved folder");}}
  TransferClient.json(origin,"api/transfers/"+code,"DELETE",null,sent.getString("token"),null);for(Uri uri:saved)try(InputStream input=context.getContentResolver().openInputStream(uri)){check(input!=null,"Saved file disappeared after revoke");}
  result.putString("result",new JSONObject().put("passed",true).put("sdk",Build.VERSION.SDK_INT).put("nativeSendService",true).put("nativeReceiveService",true).put("files",3).put("mediaStoreExactBytes",true).put("albumAndDownloads",true).put("partialFilesHidden",true).put("nativeHistory",true).put("revokeKeepsSavedFiles",true).toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("failure",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}finally{for(Uri uri:sources)try{context.getContentResolver().delete(uri,null,null);}catch(Exception ignored){}try{context.unbindService(connection);}catch(Exception ignored){}}}
}
